import os
import datetime
import time
from selenium.common.exceptions import TimeoutException, NoSuchElementException
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from selenium.webdriver.common.by import By
from selenium.webdriver.common.keys import Keys
from taf.selenium.gnb.oam.core.exceptions import OutOfRange
from selenium.webdriver.common.action_chains import ActionChains
from taf.selenium.gnb.oam.core.utils import choose_selector_way
import inspect
from functools import wraps
from robot.api import logger
from robot.utils import get_link_path
from robot.libraries.BuiltIn import BuiltIn, RobotNotRunningError


def locator_builder(func):
    @wraps(func)
    def locator_func(*args, **kwargs):
        args_name = inspect.getargspec(func)[0]
        if "locator" in args_name:
            index = args_name.index("locator")
            args = list(args)
            if len(args) > 1 and isinstance(args[index], str):
                if args[index].startswith("//"):
                    args[index] = (By.XPATH, args[index])
            if "locator" in kwargs.keys() and isinstance(kwargs["locator"], str):
                if kwargs["locator"].startswith("//"):
                    kwargs["locator"] = (By.XPATH, kwargs["locator"])
        return func(*args, **kwargs)

    return locator_func


class PagePart(object):

    def __init__(self, driver):
        self._driver = driver

    def close_browser(self):
        self._driver.quit()

    def save_screenshot(self, filename, screenshot_dir='/tmp'):
        screenshot_dir = self._create_debug_dir(screenshot_dir)
        filename = '{}_{}.png'.format(filename, datetime.datetime.now().strftime("%Y%m%d_%H%M%S"))
        self._driver.save_screenshot(os.path.join(screenshot_dir, filename))
        self._embed_to_log(os.path.join(screenshot_dir, filename), 800)
        self.info(os.path.join(screenshot_dir, filename))
        return screenshot_dir

    @staticmethod
    def _create_debug_dir(dir_path):
        debug_dir = os.path.join(dir_path, "taf_selenium_screenshot")
        if not os.path.exists(debug_dir):
            os.makedirs(debug_dir)
        return debug_dir

    def _until(self, method, timeout):
        return WebDriverWait(self._driver, timeout).until(method)

    def _until_not(self, method, timeout):
        WebDriverWait(self._driver, timeout).until_not(method)

    @locator_builder
    def _wait_for_element_by(self, locator, timeout=60):
        self._until(EC.presence_of_element_located(locator), timeout)

    @locator_builder
    def _is_element_enabled(self, locator, timeout):
        """
        Checks whether web element becomes enabled before timeout.

        :param locator: web element locator i.e. (By.ID, "someID")
        :type locator: tuple(selenium.webdriver.common.by.By, str)
        :param int timeout: time to wait for web element to be enabled, in seconds

        :return: True, if web element becomes enabled before timeout, False otherwise
        :rtype: bool
        """
        try:
            self.wait_for_enable(locator, timeout)
            return True
        except TimeoutException:
            return False

    @locator_builder
    def _is_text_present_in_element(self, locator, text, timeout):
        """
        Checks whether text becomes present in web element before timeout.

        :param tuple(selenium.webdriver.common.by.By, str) locator: web element locator i.e. (By.ID, "someID")
        :param str text: text expected to be present in web element
        :param int timeout: time to wait for text to be present in web element, in seconds

        :return: True, if text becomes present in web element before timeout, False otherwise
        :rtype: bool
        """
        try:
            self._until(EC.text_to_be_present_in_element(locator, text), timeout)
            return True
        except TimeoutException:
            return False

    @locator_builder
    def wait_for_visibility(self, locator, timeout=60):
        """
        Wait for timeout seconds until element will become visible

        :param locator: a tuple with locator for element for instance (By.ID, "someID") see selenium doc for more
        :param timeout: time until method exits with error
        """
        self._until(EC.visibility_of_element_located(locator), timeout)

    @locator_builder
    def wait_for_invisibility(self, locator, timeout=60):
        """
        Wait for timeout seconds until element will become invisible

        :param locator: a tuple with locator for element for instance (By.ID, "someID") see selenium doc for more
        :param timeout: time until method exits with error
        """
        self._until(EC.invisibility_of_element_located(locator), timeout)

    @locator_builder
    def wait_for_enable(self, locator, timeout=60):
        """
        Wait for timeout seconds until element will become enable
        check element if is enabled until timeout

        :param locator: a tuple with locator for element for instance (By.ID, "someID") see selenium doc for more
        :param timeout: time until method exits with error
        """
        return self._until(EC.element_to_be_clickable(locator), timeout)

    @locator_builder
    def insert_text_to_field(self, locator, text):
        """
        Enters given text to field with given locator.

        :param locator: ID of input element
        :param text: Text to insert into text field
        """
        elem = self._driver._wait_for_element_by(locator)
        elem.clear()
        elem.send_keys(text)

    @locator_builder
    def insert_text_to_enabled_field(self, locator, text, timeout):
        """
        Enters text into text field only if text field is enabled before timeout.

        :param tuple(selenium.webdriver.common.by.By, str) locator: text field locator i.e. (By.ID, "someID")
        :param str text: text which will be entered into text field
        :param int timeout: time to wait for text field to be enabled, in seconds

        :except selenium.common.exceptions.TimeoutException: raised if text field is disabled after timeout
        """
        self.wait_for_enable(locator, timeout)
        self.insert_text_to_field(locator[1], text)

    def input_text_to_field_by_element(self, element, value):
        """
        Enters text into text field by webelement.

        :param element: webelement
        :param value: (str, int) text, number

        :return:
        """
        element.clear()
        element.send_keys(value)

    def click_element_by_xpath(self, xpath, index=0):
        """
        Clicks element with given xpath

        :param xpath: element's xpath
        :param index: (int) index of element in returned list
        """
        self._driver.find_elements_by_xpath(xpath)[index].click()

    def select_checkbox_by_xpath(self, xpath):
        """
        select checkbox with given xpath

        :param xpath: element's xpath
        """
        checkbox = self._driver.find_element_by_xpath(xpath)
        if not checkbox.is_selected():
            checkbox.click()

    def unselect_checkbox_by_xpath(self, xpath):
        """
        unselect checkbox with given xpath

        :param xpath: element's xpath
        """
        checkbox = self._driver.find_element_by_xpath(xpath)
        if checkbox.is_selected():
            checkbox.click()

    @locator_builder
    def click_enabled_element(self, locator, timeout=60):
        """
        Clicks web element only if it is enabled before timeout.

        :param tuple(selenium.webdriver.common.by.By, str) locator: web element locator i.e. (By.ID, "someID")
        :param int timeout: time to wait for web element to be enabled, in seconds

        :except selenium.common.exceptions.TimeoutException: raised if web element is disabled after timeout
        """

        self.wait_for_enable(locator, timeout)
        self.click_button(locator)

    @locator_builder
    def element_exists(self, locator, timeout=5):
        """
        Checks whether given web element exists.

        :param tuple(selenium.webdriver.common.by.By, str) locator: web element locator i.e. (By.ID, "someID")
        :param int timeout: time to wait for element to become available, in seconds

        :return: True if web element exists, False otherwise
        :rtype: bool
        """
        try:
            self._wait_for_element_by(locator, timeout)
            return True
        except TimeoutException:
            return False

    @locator_builder
    def elements_is_visible(self, locator, timeout=5):
        """
        Checks whether given web element is visible.

        :param tuple(selenium.webdriver.common.by.By, str) locator: web element locator i.e. (By.ID, "someID")
        :param int timeout: time to wait for element to become visible, in seconds

        :return: True if web element is visible, False otherwise
        :rtype: bool
        """
        try:
            self.wait_for_visibility(locator, timeout)
            element = self._driver.find_element(*locator)
            return element.is_displayed()
        except TimeoutException:
            return False

    @locator_builder
    def is_id_present(self, locator, timeout=30):
        try:
            self._wait_for_element_by((By.ID, locator), timeout=timeout)
            self._driver.find_element_by_id(locator)
            return True
        except NoSuchElementException:
            return False

    @locator_builder
    def check_if_element_has_text(self, locator, text, timeout=5):
        """
        Checks whether given web element contains given text.

        :param tuple(selenium.webdriver.common.by.By, str) locator: web element locator i.e. (By.ID, "someID")
        :param str text: text that will be expected in web element
        :param int timeout: time to wait (in seconds) for given text to be present in web element; defaults to 5 seconds

        :return: True if web element contains given text, False otherwise
        :rtype: bool
        """
        try:
            self._until(EC.text_to_be_present_in_element(locator, text), timeout)
            return True
        except TimeoutException:
            return False

    def input_number_to_text_field(self, new_value, timeout, xpath, min_value, max_value):
        """
        Change value to new one at text filed

        :param int new_value: new number input
        :param int timeout: time to wait for element to become visible, in seconds
        :param xpath: element's xpath
        :param min_value: lowest acceptable value of the number
        :param max_value: biggest acceptable value of the number

        :raises OutOfRange: when new_value is out of range <min_value, max_value>
        """
        if new_value not in range(min_value, max_value + 1):
            raise OutOfRange('Your value: {} is out of range: {}-{}'.format(new_value, min_value, max_value))

        self._wait_for_element_by((By.XPATH, xpath), timeout)
        self.wait_for_visibility((By.XPATH, xpath), timeout)
        elem = self._driver.find_element_by_xpath(xpath)
        self.input_text_to_field_by_element(elem, new_value)

    def open_dropdown_list(self, xpath):
        """
        Open selected dropdown list by xpath

        :param xpath: element's xpath
        """
        self._wait_for_element_by((By.XPATH, xpath))
        self.wait_for_visibility((By.XPATH, xpath))
        self._driver.find_element_by_xpath(xpath).click()

    def get_attribute_by_xpath(self, xpath, attr_name, timeout=60):
        self._wait_for_element_by((By.XPATH, xpath), timeout)
        return self._driver.find_element_by_xpath(xpath).get_attribute(attr_name)

    def get_text_by_xpath(self, xpath, timeout=60):
        self._wait_for_element_by((By.XPATH, xpath), timeout)
        return self._driver.find_element_by_xpath(xpath).text.strip()

    @locator_builder
    def get_text(self, locator, timeout=60):
        self._wait_for_element_by(locator, timeout)
        return self._driver.find_element(*locator).text.strip()

    @locator_builder
    def get_attribute(self, locator, attr_name, timeout=60):
        self._wait_for_element_by(locator, timeout)
        return self._driver.find_element(*locator).get_attribute(attr_name)

    @staticmethod
    def _clear_text_of_field(elem):
        elem.send_keys(Keys.CONTROL + 'a')
        elem.send_keys(Keys.BACKSPACE)

    def _insert_text_to_field(self, text, elem):
        """
        Clear text and input a new one
        """
        self._clear_text_of_field(elem)
        elem.send_keys(text)

    def get_text_by_xpath_if_exist(self, xpath, timeout=5, _out=""):
        """
        Variation of get_text_by_path. In comparison it not wait until timeout ends, but immediately after not finding
        element it throws NoSuchElementException.

        :param xpath: Path to element which we want to acquire.
        :param timeout: int, timeout
        :param _out: Message which we want to be returned

        :return: Message from xpath, or in case of NoSuchElementException - _out defined by user.
        """
        try:
            self._wait_for_element_by((By.XPATH, xpath), timeout)
            out = self._driver.find_element_by_xpath(xpath).text.strip()
        except TimeoutException:
            out = _out
        return out

    def get_elements_xpath_list(self, xpath, timeout=60):
        elements_xpath_list = []
        self.wait_for_visibility_by_xpath(xpath, timeout)
        elements = self._driver.find_elements_by_xpath(xpath)
        for idx in range(len(elements)):
            elements_xpath_list.append(xpath + '[{}]'.format(idx + 1))
        return elements_xpath_list

    @staticmethod
    def find_element_from_group_by_text(elements, text):
        """
        To find one element by text from group

        :param elements: list, list of WebElements
        :param text: str, text value of elements

        :return: WebElement or None
        """
        for element in elements:
            if text == element.text:
                return element
        return None

    def expand_dropdown_list_and_return_elements(self, button_locator, option_locator, timeout=60):
        """
        To expand dropdown list and return all elements

        :return: WebElement
        """
        self.click_enabled_element(button_locator, timeout)
        return self._driver.find_elements(*option_locator)

    def select_element_from_dropdown_list_by_text_and_click(self, element_text, button_locator,
                                                            option_locator, timeout=60):
        elements = self.expand_dropdown_list_and_return_elements(button_locator, option_locator, timeout)
        self.find_element_from_group_by_text(elements, element_text).click()

    @locator_builder
    def click_button(self, locator):
        self._driver.find_element(*locator).click()

    @locator_builder
    def insert_text_to_enable_element_and_enter(self, locator, text, timeout=60):
        """
        Insert text to enable element and click enter
        """
        self.wait_for_enable(locator, timeout)
        element = self._driver.find_element(*locator)
        self._insert_text_to_field(text, element)
        element.send_keys(Keys.ENTER)

    @locator_builder
    def insert_text_to_enable_element(self, locator, text, timeout=60):
        """
        Insert text to enable element

        :return: WebElement
        """
        self.wait_for_enable(locator, timeout)
        self._insert_text_to_field(text, self._driver.find_element(*locator))

    @locator_builder
    def perform_element_hover(self, locator, timeout=60):
        self.wait_for_visibility(locator, timeout)
        elem = self._driver.find_element(*locator)
        ActionChains(self._driver).move_to_element(elem).perform()
        time.sleep(2)

    def perform_element_hover_by_xpath(self, xpath):
        self.wait_for_visibility((By.XPATH, xpath))
        elem = self._driver.find_element_by_xpath(xpath)
        ActionChains(self._driver).move_to_element(elem).perform()

    def wait_for_new_window_open(self, current_handle, timeout=5):
        self._until(EC.new_window_is_opened(current_handle), timeout)

    def disable_screen_lock(self, time_interval=30000):
        """
        Method to disable screen lock after idle for some minutes

        :param time_interval: int, event execution time interval, 30000 is 30s
        """
        mouse_move_event_script = 'window.interval_id = setInterval(function(){var event = new Event("mousemove"); ' \
                                  'document.body.dispatchEvent(event);}, %d)' % time_interval
        self._driver.execute_script(mouse_move_event_script)

    def enable_screen_lock(self):
        """
        Method to enable screen lock after idle for some minutes
        """
        interval_id = self._driver.execute_script("return window.interval_id")
        self._driver.execute_script("clearInterval({})".format(interval_id))

    def disable_message_box(self):
        try:
            self._wait_for_element_by((By.CLASS_NAME, "notifyjs-corner"), 30)
            self.hide_element("body > div[class=notifyjs-corner]")
        except TimeoutException:
            pass

    def refresh_page(self):
        """
        Refreshes page in web browser (same as pressing F5 key).
        """
        self._driver.refresh()

    def click_and_wait_for_corresponding_element_visible(self, click_element_xpath, corresponding_xpath, index=0,
                                                         timeout=60):
        self.wait_for_visibility((By.XPATH, click_element_xpath), timeout)
        self.click_element_by_xpath(click_element_xpath, index)
        self.wait_for_visibility((By.XPATH, corresponding_xpath), timeout)

    def select_radiobox_by_xpath(self, xpath, timeout=60):
        self.wait_for_enable((By.XPATH, xpath), timeout)
        self._driver.find_element_by_xpath(xpath).click()

    @locator_builder
    def select_radiobox(self, locator, timeout=60):
        self.wait_for_enable(locator, timeout)
        self._driver.find_element(*locator).click()

    def wait_for_visibility_by_xpath(self, xpath, timeout=60):
        self.wait_for_visibility((By.XPATH, xpath), timeout)

    def select_checkbox_by_specified_status(self, is_selected, select_xpath, click_xpath):
        """
        Some page of checkbox's click element is different of select element, so here parameters are separated, if your
        page of checkbox's click and select element are same, please input the same xpath value each.

        :param is_selected: bool, only support 'True' and 'False'
        :param select_xpath: str, it is used to check if checkbox can be selected,
        :param click_xpath: str, it is used to click checkbox

        :return:
        """
        self._wait_for_element_by((By.XPATH, select_xpath))
        if is_selected != self._driver.find_element_by_xpath(select_xpath).is_selected():
            self._driver.find_element_by_xpath(click_xpath).click()

    def get_dict_from_elements_by_xpath(self, key_xpath, value_xpath, separator=''):
        key_elements = self._driver.find_elements_by_xpath(key_xpath)
        value_elements = self._driver.find_elements_by_xpath(value_xpath)
        key_list = [item.text.strip(separator) for item in key_elements]
        value_list = [item.text for item in value_elements]
        return dict(zip(key_list, value_list))

    @choose_selector_way
    def display_element(self, select_element_script, *args, **kwargs):
        self._driver.execute_script(''.join([select_element_script, ".style.display='inline-block'"]))

    @choose_selector_way
    def hide_element(self, select_element_script, *args, **kwargs):
        self._driver.execute_script(''.join([select_element_script, ".style.display='none'"]))

    def load_file_from_hidden_button(self, button_location, button_xpath, file_path, timeout):
        """
        Actual load file button is hidden normally by developer, so we should show it , load file and then hide it

        :param button_location: str, hidden button unique location in web element
        :param button_xpath: str, hidden button's xpath
        :param file_path: str, load file's directory
        :param timeout: int, time to wait file loading

        :return:
        """
        self.display_element(button_location)
        self.wait_for_enable((By.XPATH, button_xpath), timeout)
        elem = self._driver.find_element_by_xpath(button_xpath)
        elem.clear()
        elem.send_keys(file_path)
        self.hide_element(button_location)

    def wait_for_text_present_in_attribute(self, xpath, attr_name, text, timeout=60):
        self._until(lambda x: text in self.get_attribute_by_xpath(xpath, attr_name, timeout), timeout)

    @locator_builder
    def wait_for_text_not_present_in_element(self, locator, text, timeout=60):
        self._until_not(EC.text_to_be_present_in_element(locator, text), timeout)

    @locator_builder
    def wait_for_text_present_in_element(self, locator, text, timeout=60):
        self._until(EC.text_to_be_present_in_element(locator, text), timeout)

    @locator_builder
    def get_fields_info_from_row(self, locator, timeout):
        info_list = []
        if not self.element_exists(locator, timeout):
            return info_list
        self._wait_for_element_by(locator, timeout)
        for elem in self._driver.find_elements(*locator):
            info_list.append(elem.text.strip())
        return info_list

    @locator_builder
    def press_enter_on_element(self, locator):
        """
        press enter on element
        """
        element = self._driver.find_element(*locator)
        element.send_keys(Keys.ENTER)

    @locator_builder
    def insert_text_to_enabled_element(self, locator, text, timeout=60):
        """
        Insert text to enable element

        :return: WebElement
        """
        self.wait_for_enable(locator, timeout)
        self._insert_text_to_field(text, self._driver.find_element(*locator))

    @locator_builder
    def clear_text_of_enabled_element(self, locator, timeout=60):
        self.wait_for_enable(locator, timeout)
        element = self._driver.find_element(*locator)
        self._clear_text_of_field(element)

    @locator_builder
    def get_all_matching_elements(self, locator):
        """
        This keyword will return all the selenium web objects matched to given locator
        :param locator: str, selenium locator for the objects to be matched

        :return: list selenium objects matched to given locator
        """
        return self._driver.find_elements(*locator)

    def get_text_from_all_matching_elements(self, locator):
        """
        This keyword will return a list of the text associated to elements matched for given selenium locator
        :param locator: str, selenium locator for the objects to be matched

        :return: list, List of text associated to elements matched for given selenium locator
        """
        all_text = list([])
        for element in self.get_all_matching_elements(locator):
            all_text.append(element.text)
        return all_text

    def info(self, msg, html=False):
        logger.info(msg, html)

    def debug(self, msg, html=False):
        logger.debug(msg, html)

    def warn(self, msg, html=False):
        logger.warn(msg, html)

    def _embed_to_log(self, path, width):
        # Image is shown on its own row and thus previous row is closed on
        # purpose. Depending on Robot's log structure is a bit risky.
        self.info('</td></tr><tr><td colspan="3">'
                  '<a href="{src}"><img src="{src}" width="{width}px"></a>'
                  .format(src=get_link_path(path, self.log_dir), width=width), html=True)

    @property
    def log_dir(self):
        try:
            logfile = BuiltIn().get_variable_value('${LOG FILE}')
            if logfile == 'NONE':
                return BuiltIn().get_variable_value('${OUTPUTDIR}')
            return os.path.dirname(logfile)
        except RobotNotRunningError:
            return os.getcwd()
